/* From Uiverse.io by Spacious74  - Tags: neumorphism, button, shadow, 3d button */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  background: linear-gradient(180deg, #cfcfcf, #808080);
  padding: 3px;
  border-radius: 15px;
  border: solid 1px #ebebeb;
  box-shadow: 0 3px 10px -1px #00000017, 0px 1px 5px #0000000e,
    0 10px 40px -15px #0000006e;
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ .inner {
  background: linear-gradient(180deg, #fff, #e0e0e0);
  padding: 5px;
  border-radius: 12px;
}
.__UIV_SCOPE__ .roundInner {
  font-size: 1.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-weight: bold;
  padding: 14px 12px;
  border-radius: 300px;
  box-shadow: inset 0 10px 20px #0000000c;
  background-color: #f8fafa;
  transition: all 0.4s ease;
}
.__UIV_SCOPE__ .roundInner .svg {
  transform: rotate(-45deg);
  margin-bottom: 5px;
  transition: all 0.3s ease;
}
.__UIV_SCOPE__ .roundInner:active > .svg {
  transform: translate(3px, -3px) rotate(-45deg);
}

.__UIV_SCOPE__ .button:active {
  box-shadow: none;
}
